    background-color: #e4e7ec;
    background-image:
        repeating-linear-gradient(45deg, rgba(255,255,255,0.35) 0, rgba(255,255,255,0.35) 2px, transparent 2px, transparent 4px),
        repeating-linear-gradient(-45deg, rgba(0,0,0,0.025) 0, rgba(0,0,0,0.025) 2px, transparent 2px, transparent 4px);
    border: 1px solid #b5b5b5;
    border-radius: 4px;
    box-shadow: inset 0 1px 4px rgba(0,0,0,0.18);
}
/* 聊天标题栏（微信顶部栏风格）：Char 与 谁 的聊天记录 */
.xt-text-chatTitle {
    position: relative;
    margin: 0 !important;
    padding: 0 38px !important;
    height: 32px;
    line-height: 32px !important;
    text-align: center !important;
    font-size: 12.5px !important;
    font-weight: bold !important;
    color: #222 !important;
    background: linear-gradient(to bottom, #f5f5f5, #e0e0e0) !important;
    border: 1px solid #b5b5b5 !important;
    border-radius: 4px 4px 0 0 !important;
    box-shadow: inset 0 1px 0 #fff !important;
    text-shadow: 0 1px 0 rgba(255,255,255,0.8);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.xt-text-chatTitle::before {
    content: "";
    position: absolute; left: 10px; top: 7px;
    width: 18px; height: 18px;
    background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23555555%22%20stroke-width%3D%222.8%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolyline%20points%3D%2215%2018%209%2012%2015%206%22%2F%3E%3C%2Fsvg%3E") center / contain no-repeat;
}
.xt-text-chatTitle::after {
    content: "";
    position: absolute; right: 10px; top: 7px;
    width: 18px; height: 18px;
    background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23555555%22%20stroke-width%3D%221%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Ccircle%20cx%3D%225%22%20cy%3D%2212%22%20r%3D%221.7%22%20fill%3D%22%23555555%22%2F%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%2212%22%20r%3D%221.7%22%20fill%3D%22%23555555%22%2F%3E%3Ccircle%20cx%3D%2219%22%20cy%3D%2212%22%20r%3D%221.7%22%20fill%3D%22%23555555%22%2F%3E%3C%2Fsvg%3E") center / contain no-repeat;
}
.xt-text-chatTitle:empty { display: none !important; }
.xt-bubbles { border-top: none; border-radius: 0 0 4px 4px; }

/* 气泡：微信形状（小圆角 + 顶部侧边小三角），配色沿用原来的 */
.xt-bubble-left .xt-bubble-body, .xt-bubble-left.xt-bubble-body,
.xt-bubble-right .xt-bubble-body, .xt-bubble-right.xt-bubble-body {
    position: relative;
    padding: 8px 12px !important;
    font-size: 12px !important;
    line-height: 1.5 !important;
    border-radius: 5px !important;
    box-shadow: 0 1px 2px rgba(0,0,0,0.2), inset 0 1px 0 rgba(255,255,255,0.6) !important;
}
.xt-bubble-left .xt-bubble-body, .xt-bubble-left.xt-bubble-body {
    background: linear-gradient(to bottom, #ffffff, #e9e9e9) !important;
    border: 1px solid #b0b0b0 !important;
