    text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}
.xt-bubble-right .xt-bubble-body, .xt-bubble-right.xt-bubble-body {
    background: linear-gradient(to bottom, #c9f59b, #8fd65a) !important;
    border: 1px solid #6fae3e !important;
    color: #1d3a0c !important;
    text-shadow: 0 1px 0 rgba(255,255,255,0.35);
}
/* 小三角：贴在气泡顶部侧边，像微信一样朝外 */
.xt-bubble-left .xt-bubble-body::after, .xt-bubble-left.xt-bubble-body::after {
    content: ""; position: absolute;
    top: 12px; left: -5px;
    width: 8px; height: 8px;
    background: #f4f4f4;
    border-left: 1px solid #b0b0b0;
    border-bottom: 1px solid #b0b0b0;
    transform: rotate(45deg);
}
.xt-bubble-right .xt-bubble-body::after, .xt-bubble-right.xt-bubble-body::after {
    content: ""; position: absolute;
    top: 12px; right: -5px;
    width: 8px; height: 8px;
    background: #b2e67f;
    border-right: 1px solid #6fae3e;
    border-bottom: 1px solid #6fae3e;
    transform: rotate(-45deg);
}
.xt-bubble-body:empty { display: none !important; }

/* ======================================================================
   新增三块：推特帖子 / 韩系论坛 / 小剧场（用 :has() 区分各自的卡片；图标全部为 SVG）
