  --nj-q-me-name:rgba(255,255,255,.8); --nj-q-me-text:rgba(255,255,255,.55); --nj-q-me-line:rgba(255,255,255,.18);
  --voice-me-color:#ffffff; --voice-me-bar-active:#ffffff; --voice-me-bar-inactive:rgba(255,255,255,.3);
  --voice-them-color:#333333; --voice-them-bar-active:#333333; --voice-them-bar-inactive:rgba(51,51,51,.3);
